function farthestSeatGap(seats: number[]): number {
  const n = seats.length;
  const left = new Array(n).fill(Infinity), right = new Array(n).fill(Infinity);
  for (let i = 0; i < n; i++) left[i] = seats[i] ? 0 : i > 0 ? left[i - 1] + 1 : Infinity;
  for (let i = n - 1; i >= 0; i--) right[i] = seats[i] ? 0 : i < n - 1 ? right[i + 1] + 1 : Infinity;
  let best = 0;
  for (let i = 0; i < n; i++) if (!seats[i]) best = Math.max(best, Math.min(left[i], right[i]));
  return best;
}

