class Solution:
    def farthestSeatGap(self, seats: List[int]) -> int:
        n = len(seats)
        left, right = [math.inf] * n, [math.inf] * n
        for i in range(n):
            if seats[i]:
                left[i] = 0
            elif i > 0:
                left[i] = left[i - 1] + 1
        for i in range(n - 1, -1, -1):
            if seats[i]:
                right[i] = 0
            elif i < n - 1:
                right[i] = right[i + 1] + 1
        return max(min(left[i], right[i]) for i in range(n) if not seats[i])

