function farthestSeatGap(seats: number[]): number {
  let prev = -1, best = 0;
  for (let i = 0; i < seats.length; i++) {
    if (!seats[i]) continue;
    best = Math.max(best, prev === -1 ? i : Math.floor((i - prev) / 2));
    prev = i;
  }
  return Math.max(best, seats.length - 1 - prev);
}

